const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const root_module = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{
        .name = "kvhttp",
        .root_module = root_module,
    });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    if (b.args) |args| run_cmd.addArgs(args);
    b.step("run", "Run the server").dependOn(&run_cmd.step);

    const tests = b.addTest(.{ .root_module = root_module });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Request routing for the key-value API.

const App = @This();

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const http = @import("http.zig");
const Store = @import("Store.zig");

store: *Store,

pub const max_key_len = 64;

pub const Error = Allocator.Error || Io.Cancelable;

/// Produces the response for `req`. Response memory is allocated with `arena`.
pub fn handle(app: App, io: Io, arena: Allocator, req: http.Request) Error!http.Response {
    if (std.mem.eql(u8, req.path, "/health")) {
        if (!isMethod(req, "GET")) return methodNotAllowed("GET");
        return .{ .status = .ok, .body = "ok", .content_type = "text/plain; charset=utf-8" };
    }
    if (std.mem.eql(u8, req.path, "/kv")) {
        if (!isMethod(req, "GET")) return methodNotAllowed("GET");
        return .{ .status = .ok, .body = try app.listKeys(io, arena), .content_type = "application/json" };
    }
    if (std.mem.startsWith(u8, req.path, "/kv/")) {
        const key = req.path["/kv/".len..];
        if (!isValidKey(key)) return .{ .status = .bad_request };
        return app.handleKey(io, arena, req, key);
    }
    return .{ .status = .not_found };
}

fn handleKey(app: App, io: Io, arena: Allocator, req: http.Request, key: []const u8) Error!http.Response {
    if (isMethod(req, "GET")) {
        const value = try app.store.get(io, arena, key) orelse return .{ .status = .not_found };
        return .{ .status = .ok, .body = value, .content_type = "application/octet-stream" };
    }
    if (isMethod(req, "PUT")) {
        return switch (try app.store.put(io, key, req.body)) {
            .created => .{ .status = .created },
            .replaced => .{ .status = .ok },
        };
    }
    if (isMethod(req, "DELETE")) {
        const deleted = try app.store.delete(io, key);
        return .{ .status = if (deleted) .no_content else .not_found };
    }
    return methodNotAllowed("GET, PUT, DELETE");
}

fn listKeys(app: App, io: Io, arena: Allocator) Error![]const u8 {
    const keys = try app.store.sortedKeys(io, arena);
    var out: Io.Writer.Allocating = .init(arena);
    std.json.Stringify.value(keys, .{}, &out.writer) catch return error.OutOfMemory;
    return out.written();
}

fn isMethod(req: http.Request, method: []const u8) bool {
    return std.mem.eql(u8, req.method, method);
}

fn methodNotAllowed(allow: []const u8) http.Response {
    return .{ .status = .method_not_allowed, .allow = allow };
}

/// A key matches `[A-Za-z0-9_-]{1,64}`.
pub fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > max_key_len) return false;
    for (key) |c| {
        if (!std.ascii.isAlphanumeric(c) and c != '_' and c != '-') return false;
    }
    return true;
}

const testing = std.testing;

test isValidKey {
    try testing.expect(isValidKey("a"));
    try testing.expect(isValidKey("A-z_09"));
    try testing.expect(isValidKey("k" ** 64));
    try testing.expect(!isValidKey(""));
    try testing.expect(!isValidKey("k" ** 65));
    try testing.expect(!isValidKey("a/b"));
    try testing.expect(!isValidKey("bad.key"));
    try testing.expect(!isValidKey("caf\xc3\xa9"));
}

test "routing" {
    const io = testing.io;
    var arena_state: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    var store: Store = .init(testing.allocator);
    defer store.deinit();
    const app: App = .{ .store = &store };

    const Case = struct { method: []const u8, path: []const u8, body: []const u8 = "", status: http.Status, response: ?[]const u8 = null };
    const cases = [_]Case{
        .{ .method = "GET", .path = "/health", .status = .ok, .response = "ok" },
        .{ .method = "POST", .path = "/health", .status = .method_not_allowed },
        .{ .method = "GET", .path = "/kv", .status = .ok, .response = "[]" },
        .{ .method = "PUT", .path = "/kv/b", .body = "2", .status = .created },
        .{ .method = "PUT", .path = "/kv/a", .body = "1", .status = .created },
        .{ .method = "PUT", .path = "/kv/a", .body = "one", .status = .ok },
        .{ .method = "GET", .path = "/kv/a", .status = .ok, .response = "one" },
        .{ .method = "GET", .path = "/kv", .status = .ok, .response = "[\"a\",\"b\"]" },
        .{ .method = "DELETE", .path = "/kv", .status = .method_not_allowed },
        .{ .method = "PATCH", .path = "/kv/a", .status = .method_not_allowed },
        .{ .method = "PATCH", .path = "/kv/a.b", .status = .bad_request },
        .{ .method = "GET", .path = "/kv/", .status = .bad_request },
        .{ .method = "GET", .path = "/kv/a/b", .status = .bad_request },
        .{ .method = "DELETE", .path = "/kv/a", .status = .no_content },
        .{ .method = "DELETE", .path = "/kv/a", .status = .not_found },
        .{ .method = "GET", .path = "/kv/a", .status = .not_found },
        .{ .method = "GET", .path = "/nope", .status = .not_found },
        .{ .method = "GET", .path = "/health/", .status = .not_found },
    };
    for (cases) |c| {
        const resp = try app.handle(io, arena, .{ .method = c.method, .path = c.path, .body = c.body });
        try testing.expectEqual(c.status, resp.status);
        if (c.response) |expected| try testing.expectEqualStrings(expected, resp.body);
    }
}

//! Thread-safe in-memory key-value store.
//!
//! The store owns copies of every key and value it holds. All access is
//! serialized by a single mutex; critical sections never perform I/O, so
//! contention stays low even with many concurrent connections.

const Store = @This();

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

gpa: Allocator,
mutex: Io.Mutex = .init,
map: std.StringHashMapUnmanaged([]u8) = .empty,

pub const PutResult = enum { created, replaced };

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(s: *Store) void {
    var it = s.map.iterator();
    while (it.next()) |entry| {
        s.gpa.free(entry.key_ptr.*);
        s.gpa.free(entry.value_ptr.*);
    }
    s.map.deinit(s.gpa);
    s.* = undefined;
}

/// Stores a copy of `value` under `key`, replacing any previous value.
pub fn put(s: *Store, io: Io, key: []const u8, value: []const u8) (Allocator.Error || Io.Cancelable)!PutResult {
    // Copy outside the lock; large values should not stall other clients.
    const owned_value = try s.gpa.dupe(u8, value);
    errdefer s.gpa.free(owned_value);
    const owned_key = try s.gpa.dupe(u8, key);
    var key_used = false;
    defer if (!key_used) s.gpa.free(owned_key);

    const old_value: ?[]u8 = blk: {
        try s.mutex.lock(io);
        defer s.mutex.unlock(io);
        const gop = try s.map.getOrPut(s.gpa, owned_key);
        if (gop.found_existing) {
            const old = gop.value_ptr.*;
            gop.value_ptr.* = owned_value;
            break :blk old;
        }
        key_used = true;
        gop.value_ptr.* = owned_value;
        break :blk null;
    };

    if (old_value) |old| {
        s.gpa.free(old);
        return .replaced;
    }
    return .created;
}

/// Returns a copy of the value stored under `key`, allocated with `allocator`,
/// or null if the key is absent.
pub fn get(s: *Store, io: Io, allocator: Allocator, key: []const u8) (Allocator.Error || Io.Cancelable)!?[]u8 {
    try s.mutex.lock(io);
    defer s.mutex.unlock(io);
    const value = s.map.get(key) orelse return null;
    return try allocator.dupe(u8, value);
}

/// Removes `key`; returns whether it was present.
pub fn delete(s: *Store, io: Io, key: []const u8) Io.Cancelable!bool {
    const removed = blk: {
        try s.mutex.lock(io);
        defer s.mutex.unlock(io);
        break :blk s.map.fetchRemove(key);
    };
    const kv = removed orelse return false;
    s.gpa.free(kv.key);
    s.gpa.free(kv.value);
    return true;
}

/// Returns copies of all keys, sorted ascending by byte value, allocated with
/// `allocator`. The caller owns the returned slice and its elements.
pub fn sortedKeys(s: *Store, io: Io, allocator: Allocator) (Allocator.Error || Io.Cancelable)![][]const u8 {
    const keys = blk: {
        try s.mutex.lock(io);
        defer s.mutex.unlock(io);
        const keys = try allocator.alloc([]const u8, s.map.count());
        var filled: usize = 0;
        errdefer {
            for (keys[0..filled]) |k| allocator.free(k);
            allocator.free(keys);
        }
        var it = s.map.keyIterator();
        while (it.next()) |key| : (filled += 1) {
            keys[filled] = try allocator.dupe(u8, key.*);
        }
        break :blk keys;
    };
    std.mem.sortUnstable([]const u8, keys, {}, lessThan);
    return keys;
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.lessThan(u8, a, b);
}

test "put, get, replace, delete" {
    const io = std.testing.io;
    const gpa = std.testing.allocator;
    var store: Store = .init(gpa);
    defer store.deinit();

    try std.testing.expectEqual(.created, try store.put(io, "a", "hello"));
    try std.testing.expectEqual(.replaced, try store.put(io, "a", "world"));

    const value = (try store.get(io, gpa, "a")).?;
    defer gpa.free(value);
    try std.testing.expectEqualStrings("world", value);

    try std.testing.expect(try store.delete(io, "a"));
    try std.testing.expect(!try store.delete(io, "a"));
    try std.testing.expectEqual(null, try store.get(io, gpa, "a"));
}

test "sortedKeys" {
    const io = std.testing.io;
    const gpa = std.testing.allocator;
    var store: Store = .init(gpa);
    defer store.deinit();

    for ([_][]const u8{ "b", "a", "_", "C", "-" }) |k| _ = try store.put(io, k, "");
    const keys = try store.sortedKeys(io, gpa);
    defer {
        for (keys) |k| gpa.free(k);
        gpa.free(keys);
    }
    const expected = [_][]const u8{ "-", "C", "_", "a", "b" };
    try std.testing.expectEqual(expected.len, keys.len);
    for (expected, keys) |e, k| try std.testing.expectEqualStrings(e, k);
}

//! Minimal HTTP/1.1 request parsing and response serialization.
//!
//! The server handles exactly one request per connection, so the parser only
//! needs to read a single request head and its body.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

pub const Status = std.http.Status;

/// Upper bound on the request line plus headers, including the blank line.
pub const max_header_bytes = 64 * 1024;
/// Upper bound on a request body.
pub const max_body_bytes = 1024 * 1024;

pub const Request = struct {
    method: []const u8,
    /// Request target with any query string removed.
    path: []const u8,
    body: []const u8,
};

pub const Response = struct {
    status: Status,
    body: []const u8 = "",
    content_type: ?[]const u8 = null,
    allow: ?[]const u8 = null,

    pub fn write(r: Response, w: *Io.Writer) Io.Writer.Error!void {
        try w.print("HTTP/1.1 {d} {s}\r\n", .{ @intFromEnum(r.status), reasonPhrase(r.status) });
        if (r.content_type) |value| try w.print("Content-Type: {s}\r\n", .{value});
        if (r.allow) |value| try w.print("Allow: {s}\r\n", .{value});
        try w.print("Content-Length: {d}\r\nConnection: close\r\n\r\n", .{r.body.len});
        try w.writeAll(r.body);
    }
};

fn reasonPhrase(status: Status) []const u8 {
    return switch (status) {
        .payload_too_large => "Content Too Large", // RFC 9110 name
        else => status.phrase() orelse "",
    };
}

/// Protocol violations that are answered with an error response.
pub const ProtocolError = error{
    BadRequest,
    HeaderTooLarge,
    ContentTooLarge,
    NotImplemented,
};

pub fn statusFor(err: ProtocolError) Status {
    return switch (err) {
        error.BadRequest => .bad_request,
        error.HeaderTooLarge => .request_header_fields_too_large,
        error.ContentTooLarge => .payload_too_large,
        error.NotImplemented => .not_implemented,
    };
}

pub const ReadError = ProtocolError || Allocator.Error || Io.Reader.Error;

/// Reads one request from `r`, whose buffer must hold at least
/// `max_header_bytes`. Method, path, and body are allocated with
/// `arena`, so they remain valid after the reader's buffer is reused.
///
/// `error.EndOfStream` and `error.ReadFailed` mean the client went away
/// before sending a complete request.
pub fn readRequest(r: *Io.Reader, arena: Allocator) ReadError!Request {
    const head_len = try fillHead(r);
    const head = r.buffered()[0..head_len];

    var lines = std.mem.splitSequence(u8, head, "\r\n");
    var parts = std.mem.splitScalar(u8, lines.first(), ' ');
    const method = parts.first();
    const target = parts.next() orelse return error.BadRequest;
    const version = parts.next() orelse return error.BadRequest;
    if (parts.next() != null or !std.mem.startsWith(u8, version, "HTTP/")) return error.BadRequest;

    // Only the framing headers matter to this server. Later duplicates win.
    var content_length: ?[]const u8 = null;
    var transfer_encoding: ?[]const u8 = null;
    while (lines.next()) |line| {
        const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.BadRequest;
        const name = line[0..colon];
        if (name.len == 0 or std.mem.trim(u8, name, &std.ascii.whitespace).len != name.len)
            return error.BadRequest;
        const value = std.mem.trim(u8, line[colon + 1 ..], &std.ascii.whitespace);
        if (std.ascii.eqlIgnoreCase(name, "content-length")) {
            content_length = value;
        } else if (std.ascii.eqlIgnoreCase(name, "transfer-encoding")) {
            transfer_encoding = value;
        }
    }

    const path_end = std.mem.indexOfScalar(u8, target, '?') orelse target.len;
    const request: Request = .{
        .method = try arena.dupe(u8, method),
        .path = try arena.dupe(u8, target[0..path_end]),
        .body = "",
    };

    // Validate framing before consuming the head; the head slices above
    // alias the reader buffer and are invalidated by further reads.
    const framing: Framing = if (transfer_encoding) |te| blk: {
        if (!std.ascii.eqlIgnoreCase(te, "chunked")) return error.NotImplemented;
        break :blk .chunked;
    } else if (content_length) |cl| .{ .length = try parseContentLength(cl) } else .{ .length = 0 };

    r.toss(head_len + 4);

    var result = request;
    result.body = switch (framing) {
        .length => |n| try r.readAlloc(arena, n),
        .chunked => try readChunked(r, arena),
    };
    return result;
}

const Framing = union(enum) {
    length: usize,
    chunked,
};

/// Buffers input until the head terminator is seen; returns the head length
/// excluding the terminating "\r\n\r\n". Stream readers must have a buffer of
/// at least `max_header_bytes`.
fn fillHead(r: *Io.Reader) (ProtocolError || Io.Reader.Error)!usize {
    const terminator = "\r\n\r\n";
    var scanned: usize = 0;
    while (true) {
        const buffered = r.buffered();
        if (std.mem.indexOfPos(u8, buffered, scanned, terminator)) |end| return end;
        scanned = buffered.len -| (terminator.len - 1);
        if (buffered.len >= max_header_bytes) return error.HeaderTooLarge;
        try r.fillMore();
    }
}

fn parseContentLength(text: []const u8) ProtocolError!usize {
    if (text.len == 0) return error.BadRequest;
    for (text) |c| if (!std.ascii.isDigit(c)) return error.BadRequest;
    const n = std.fmt.parseInt(usize, text, 10) catch |err| switch (err) {
        error.Overflow => return error.ContentTooLarge,
        error.InvalidCharacter => unreachable, // digits checked above
    };
    if (n > max_body_bytes) return error.ContentTooLarge;
    return n;
}

fn readChunked(r: *Io.Reader, arena: Allocator) ReadError![]u8 {
    var body: std.ArrayList(u8) = .empty;
    while (true) {
        const line = try takeLine(r);
        const size_end = std.mem.indexOfScalar(u8, line, ';') orelse line.len;
        const size_text = std.mem.trim(u8, line[0..size_end], &std.ascii.whitespace);
        const size = std.fmt.parseInt(usize, size_text, 16) catch |err| switch (err) {
            error.Overflow => return error.ContentTooLarge,
            error.InvalidCharacter => return error.BadRequest,
        };
        if (size == 0) {
            // Discard trailers up to the terminating blank line.
            while ((try takeLine(r)).len != 0) {}
            return body.toOwnedSlice(arena);
        }
        if (size > max_body_bytes - body.items.len) return error.ContentTooLarge;
        try r.readSliceAll(try body.addManyAsSlice(arena, size));
        if (!std.mem.eql(u8, try r.take(2), "\r\n")) return error.BadRequest;
    }
}

/// Takes one CRLF-terminated line, returning it without the terminator.
fn takeLine(r: *Io.Reader) (ProtocolError || Io.Reader.Error)![]u8 {
    const line = r.takeDelimiterInclusive('\n') catch |err| switch (err) {
        error.StreamTooLong => return error.BadRequest,
        else => |e| return e,
    };
    if (line.len < 2 or line[line.len - 2] != '\r') return error.BadRequest;
    return line[0 .. line.len - 2];
}

const testing = std.testing;

fn parse(arena: Allocator, raw: []const u8) ReadError!Request {
    var r: Io.Reader = .fixed(raw);
    return readRequest(&r, arena);
}

test "parses request with content length" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const req = try parse(arena.allocator(), "PUT /kv/a?x=1 HTTP/1.1\r\nHost: x\r\ncontent-length: 5\r\n\r\nhello");
    try testing.expectEqualStrings("PUT", req.method);
    try testing.expectEqualStrings("/kv/a", req.path);
    try testing.expectEqualStrings("hello", req.body);
}

test "parses chunked body" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const req = try parse(arena.allocator(), "PUT /kv/a HTTP/1.1\r\nTransfer-Encoding: Chunked\r\n\r\n" ++
        "5;ext=1\r\nhello\r\n6\r\n world\r\n0\r\nTrailer: x\r\n\r\n");
    try testing.expectEqualStrings("hello world", req.body);
}

test "rejects malformed requests" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    try testing.expectError(error.BadRequest, parse(a, "GET /\r\n\r\n"));
    try testing.expectError(error.BadRequest, parse(a, "GET / FTP/1.0\r\n\r\n"));
    try testing.expectError(error.BadRequest, parse(a, "GET  / HTTP/1.1\r\n\r\n"));
    try testing.expectError(error.BadRequest, parse(a, "GET / HTTP/1.1\r\nNoColon\r\n\r\n"));
    try testing.expectError(error.BadRequest, parse(a, "GET / HTTP/1.1\r\nName : v\r\n\r\n"));
    try testing.expectError(error.BadRequest, parse(a, "GET / HTTP/1.1\r\nContent-Length: -1\r\n\r\n"));
    try testing.expectError(error.ContentTooLarge, parse(a, "GET / HTTP/1.1\r\nContent-Length: 1048577\r\n\r\n"));
    try testing.expectError(error.NotImplemented, parse(a, "GET / HTTP/1.1\r\nTransfer-Encoding: gzip\r\n\r\n"));
    try testing.expectError(error.EndOfStream, parse(a, "GET / HTTP/1.1\r\nContent-Length: 4\r\n\r\nab"));
    try testing.expectError(error.EndOfStream, parse(a, "GET / HTTP/1.1\r\n"));
}

test "serializes response" {
    var buf: [256]u8 = undefined;
    var w: Io.Writer = .fixed(&buf);
    try (Response{ .status = .method_not_allowed, .allow = "GET" }).write(&w);
    try testing.expectEqualStrings(
        "HTTP/1.1 405 Method Not Allowed\r\nAllow: GET\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
        w.buffered(),
    );
}

//! kvhttp: an in-memory HTTP/1.1 key-value server.
//!
//! Usage: app <port>
//!
//! Listens on 127.0.0.1:<port>, handles one request per connection, and
//! serves each connection on its own concurrent task.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const http = @import("http.zig");
const App = @import("App.zig");
const Store = @import("Store.zig");

const log = std.log.scoped(.kvhttp);

pub fn main(init: std.process.Init) !u8 {
    const io = init.io;
    const gpa = init.gpa;

    const args = try init.minimal.args.toSlice(init.arena.allocator());
    const port = (if (args.len == 2) parsePort(args[1]) else null) orelse {
        try Io.File.stderr().writeStreamingAll(io, "usage: app <port>\n");
        return 2;
    };

    var store: Store = .init(gpa);
    defer store.deinit();
    const app: App = .{ .store = &store };

    const address: Io.net.IpAddress = .{ .ip4 = .loopback(port) };
    var server = try address.listen(io, .{ .kernel_backlog = 1024, .reuse_address = true });
    defer server.deinit(io);

    var connections: Io.Group = .init;
    defer connections.cancel(io);

    while (true) {
        const stream = server.accept(io) catch |err| switch (err) {
            error.ConnectionAborted, error.BlockedByFirewall, error.ProtocolFailure => continue,
            error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded, error.SystemResources => {
                log.warn("accept failed: {t}", .{err});
                try io.sleep(.fromMilliseconds(10), .awake);
                continue;
            },
            else => |e| return e,
        };
        connections.concurrent(io, serveConnection, .{ app, io, gpa, stream }) catch |err| {
            log.warn("dropping connection: {t}", .{err});
            stream.close(io);
        };
    }
}

fn parsePort(text: []const u8) ?u16 {
    if (text.len == 0) return null;
    for (text) |c| if (!std.ascii.isDigit(c)) return null;
    const port = std.fmt.parseInt(u16, text, 10) catch return null;
    return if (port == 0) null else port;
}

/// After an error response the client may still be sending a request we did
/// not consume. Closing with unread input makes the kernel reset the
/// connection, which can destroy the response in flight, so drain up to this
/// many bytes first.
const max_linger_bytes = 2 * http.max_body_bytes;

fn serveConnection(app: App, io: Io, gpa: Allocator, stream: Io.net.Stream) Io.Cancelable!void {
    defer stream.close(io);

    var arena_state: std.heap.ArenaAllocator = .init(gpa);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const recv_buffer = arena.alloc(u8, http.max_header_bytes) catch return;
    var reader = stream.reader(io, recv_buffer);
    var send_buffer: [4096]u8 = undefined;
    var writer = stream.writer(io, &send_buffer);

    const outcome = respond(app, io, arena, &reader.interface) catch |err| switch (err) {
        // The client went away or sent a truncated request; nothing to answer.
        error.EndOfStream => return,
        error.ReadFailed => return if (reader.err) |e| switch (e) {
            error.Canceled => error.Canceled,
            else => {},
        },
        error.Canceled => return error.Canceled,
    };

    outcome.response.write(&writer.interface) catch return;
    writer.interface.flush() catch return;

    if (outcome.unread_input) {
        stream.shutdown(io, .send) catch return;
        _ = reader.interface.discardShort(max_linger_bytes) catch {};
    }
}

const Outcome = struct {
    response: http.Response,
    /// The request was rejected before it was fully read.
    unread_input: bool = false,
};

fn respond(app: App, io: Io, arena: Allocator, reader: *Io.Reader) (Io.Reader.Error || Io.Cancelable)!Outcome {
    const req = http.readRequest(reader, arena) catch |err| switch (err) {
        error.OutOfMemory => return .{ .response = internalError(err), .unread_input = true },
        error.EndOfStream, error.ReadFailed => |e| return e,
        else => |e| return .{ .response = .{ .status = http.statusFor(e) }, .unread_input = true },
    };
    const response = app.handle(io, arena, req) catch |err| switch (err) {
        error.OutOfMemory => internalError(err),
        error.Canceled => return error.Canceled,
    };
    return .{ .response = response };
}

fn internalError(err: anyerror) http.Response {
    log.err("unhandled error while serving request: {t}", .{err});
    return .{ .status = .internal_server_error };
}

test {
    _ = @import("http.zig");
    _ = @import("App.zig");
    _ = @import("Store.zig");
}

test parsePort {
    try std.testing.expectEqual(8080, parsePort("8080"));
    try std.testing.expectEqual(80, parsePort("0080"));
    try std.testing.expectEqual(null, parsePort("0"));
    try std.testing.expectEqual(null, parsePort("65536"));
    try std.testing.expectEqual(null, parsePort("+80"));
    try std.testing.expectEqual(null, parsePort(""));
}
